<script setup>
import {computed,nextTick,onUnmounted,reactive,ref,watch} from 'vue'
import {workbenchRequest,uploadCaseEvidence,getCaseEvidence} from '../lib/backends'
import {formDraftKey,readFormDraft,writeFormDraft,clearFormDraft,copyForm,sameForm} from '../lib/formDrafts'
import '../styles/service-followup.css'
import ClosurePlanForm from './ClosurePlanForm.vue'
const closurePlan=ref({})
watch(closurePlan,value=>{if(props?.conversation)writeFormDraft(formDraftKey(props.settings,'post-closure',props.conversation.id),value)},{deep:true})
const props=defineProps({conversation:Object,settings:Object,members:Array})
const emit=defineEmits(['changed'])
const data=ref(null),busy=ref(false),loading=ref(true),error=ref(''),notice=ref(''),errorBox=ref(null),draftNotice=ref('')
const result=reactive({status:'pending',occurred_at:'',note:'',owner:'',next_action:'',due_at:''})
const material=reactive({id:'',name:'',required:true,owner:'',due_at:'',status:'missing',note:'',expected_revision:null})
const suggestionKeys=ref([]),suggestionOwner=ref(''),suggestionDue=ref(''),suggestionsRequired=ref(false)
const resultBase=ref(0),resultConflict=ref(false),materialConflict=ref(false)
const file=ref(null),fileReminder=ref(null),uploadMaterial=ref(''),sourceNote=ref(''),uploadKey=ref(null),archiveNote=ref(''),showArchived=ref(false),preview=ref(null)
const resultSection=ref(null),materialSection=ref(null)
const resultNames={pending:'等待客户确认',confirmed:'客户确认解决',disputed:'客户不认可',unreachable:'无法联系'}
const materialNames={missing:'待收集',received:'已收到 · 待核验',verified:'已核验',waived:'已豁免',withdrawn:'已撤回'}
const visibleMaterials=computed(()=>data.value?.materials.filter(m=>showArchived.value||m.status!=='withdrawn')||[])
const uploadMaterials=computed(()=>data.value?.materials.filter(m=>m.status!=='withdrawn')||[])
const attachments=computed(()=>data.value?.attachments.filter(a=>showArchived.value||!a.archived)||[])
const fingerprint=()=>[props.conversation.id,props.settings.userId,props.settings.workspaceId].join(':')
const api=(p,m='GET',b)=>workbenchRequest(props.settings,p,m,b)
const localTime=value=>value?new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value)).replace(' ','T'):''
const iso=value=>value?new Date(value+':00+08:00').toISOString():null
const display=value=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'未记录'
const defaultOwner=()=>props.members?.some(m=>m.id===props.conversation.owner)?props.conversation.owner:props.settings.userId
let generation=0,hydrating=true,draftKey='',resultInitial={},materialInitial={}
const envelope=()=>readFormDraft(draftKey)||{materials:{}}
function mutateDraft(fn){if(!draftKey)return;const d=envelope();d.materials ||= {};fn(d);if(!writeFormDraft(draftKey,d))draftNotice.value='浏览器无法保存未提交内容，请先提交表单再切换页面'}
function resultFields(r){return {status:r?.status||'pending',occurred_at:localTime(r?.occurred_at||new Date()),note:r?.note||'',owner:r?.owner||defaultOwner(),next_action:r?.next_action||'',due_at:localTime(r?.due_at)}}
function materialFields(m){return {id:m?.id||'',name:m?.name||'',required:m?.required??true,owner:m?.owner||defaultOwner(),due_at:localTime(m?.due_at),status:m?.status||'missing',note:'',expected_revision:m?.revision||null}}
function loadMaterial(m,restore=true){hydrating=true;const fresh=materialFields(m);materialInitial=copyForm(fresh);Object.assign(material,fresh);const saved=restore?envelope().materials?.[fresh.id||'new']:null;if(saved)Object.assign(material,saved);materialConflict.value=!!saved&&!!fresh.id&&saved.expected_revision!==fresh.expected_revision;hydrating=false}
function newMaterial(){loadMaterial(null);mutateDraft(d=>{d.selection='new'})}
function chooseMaterial(m){loadMaterial(m);mutateDraft(d=>{d.selection=m.id})}
watch(result,()=>{if(hydrating)return;mutateDraft(d=>{if(sameForm(result,resultInitial))delete d.result;else d.result={fields:copyForm(result),base:resultBase.value}})},{deep:true,flush:'sync'})
watch(material,()=>{if(hydrating)return;mutateDraft(d=>{const id=material.id||'new';if(sameForm(material,materialInitial))delete d.materials[id];else d.materials[id]=copyForm(material);d.selection=id})},{deep:true,flush:'sync'})
watch([uploadMaterial,sourceNote,archiveNote,fileReminder,uploadKey],()=>{if(hydrating)return;mutateDraft(d=>{d.upload={material_id:uploadMaterial.value,note:sourceNote.value,file:fileReminder.value,key:uploadKey.value};d.archiveNote=archiveNote.value})},{deep:true,flush:'sync'})
watch([suggestionKeys,suggestionOwner,suggestionDue,suggestionsRequired],()=>{if(hydrating)return;mutateDraft(d=>{d.suggestions={keys:suggestionKeys.value,owner:suggestionOwner.value,due:suggestionDue.value,required:suggestionsRequired.value}})},{deep:true,flush:'sync'})
function addSuggestions(){const key=draftKey;return run(async()=>{await api('/conversations/'+props.conversation.id+'/material-suggestions','POST',{user_id:props.settings.userId,keys:suggestionKeys.value,owner:suggestionOwner.value,due_at:iso(suggestionDue.value),required:suggestionsRequired.value});const d=readFormDraft(key)||{};delete d.suggestions;writeFormDraft(key,d)},'所选材料已建立为待收集；已有材料保留，不重复创建或改变核验状态')}
function rebaseResult(){resultBase.value=data.value.result_revision;resultConflict.value=false;mutateDraft(d=>{d.result={fields:copyForm(result),base:resultBase.value}});notice.value='已保留你的草稿；请对照当前记录核对后再提交'}
function rebaseMaterial(){const current=data.value.materials.find(m=>m.id===material.id);if(!current)return;material.expected_revision=current.revision;materialConflict.value=false;notice.value='已保留材料草稿；请对照当前材料状态核对后再提交'}
function discardResult(){mutateDraft(d=>{delete d.result});hydrating=true;Object.assign(result,resultFields(data.value.customer_result));resultInitial=copyForm(result);resultBase.value=data.value.result_revision;resultConflict.value=false;hydrating=false}
function discardMaterial(){const id=material.id;mutateDraft(d=>{delete d.materials[id||'new']});loadMaterial(data.value.materials.find(m=>m.id===id),false)}
function closePreview(){if(preview.value)URL.revokeObjectURL(preview.value.url);preview.value=null}
async function load(){const token=++generation;loading.value=true;try{const value=await api('/conversations/'+props.conversation.id+'/followup?user_id='+encodeURIComponent(props.settings.userId));if(token!==generation)return;hydrating=true;data.value=value;const d=envelope();Object.assign(result,resultFields(value.customer_result));resultInitial=copyForm(result);resultBase.value=value.result_revision;resultConflict.value=false;if(d.result){Object.assign(result,d.result.fields);resultBase.value=d.result.base;resultConflict.value=d.result.base!==value.result_revision}
 suggestionKeys.value=(d.suggestions?.keys||[]).filter(key=>value.material_suggestions?.some(s=>s.key===key&&!s.existing_id));suggestionOwner.value=d.suggestions?.owner||defaultOwner();suggestionDue.value=d.suggestions?.due||localTime(new Date(Date.now()+86400000));suggestionsRequired.value=d.suggestions?.required??false;
 uploadMaterial.value=d.upload?.material_id||value.materials.find(m=>m.status!=='withdrawn')?.id||'';sourceNote.value=d.upload?.note||'';archiveNote.value=d.archiveNote||'';fileReminder.value=d.upload?.file||null;uploadKey.value=d.upload?.key||null;hydrating=false;loadMaterial(value.materials.find(m=>m.id===d.selection));
 if(d.result||Object.keys(d.materials||{}).length||d.upload?.note||d.archiveNote)draftNotice.value='未提交内容已保存在此用户、工作范围和事项下；切页或刷新后可恢复';
 }catch(e){if(token===generation)error.value=e.message}finally{if(token===generation){hydrating=false;loading.value=false}}}
watch(()=>[props.conversation.id,props.settings.userId,props.settings.workspaceId,props.conversation.service_round,props.conversation.result_revision,props.conversation.status],()=>{hydrating=true;closurePlan.value=readFormDraft(formDraftKey(props.settings,'post-closure',props.conversation.id))||{};draftKey=formDraftKey(props.settings,'followup',props.conversation.id);data.value=null;error.value='';notice.value='';draftNotice.value='';file.value=null;closePreview();load()},{immediate:true})
onUnmounted(()=>{generation++;closePreview()})
async function saveClosurePlan(){await run(()=>api('/conversations/'+props.conversation.id+'/closure-plan','PUT',{user_id:props.settings.userId,plan:closurePlan.value}),'后续安排已保存，客户原始反馈保持独立');if(!error.value)closurePlan.value={}}
async function run(fn,message,refresh=true){if(busy.value||loading.value)return;const scope=fingerprint();busy.value=true;error.value='';notice.value='';try{await fn();if(scope!==fingerprint())return;if(refresh)await load();notice.value=message;if(refresh)emit('changed')}catch(e){if(scope===fingerprint()){error.value=e.message;await nextTick();errorBox.value?.focus()}}finally{busy.value=false}}
function saveResult(){const key=draftKey;return run(async()=>{await api('/conversations/'+props.conversation.id+'/customer-result','PUT',{user_id:props.settings.userId,...result,occurred_at:iso(result.occurred_at),due_at:iso(result.due_at),expected_revision:resultBase.value});const d=readFormDraft(key)||{};delete d.result;writeFormDraft(key,d)},'客户结果已人工登记；内部结案与客户反馈分别保留')}
function saveMaterial(){const editing=!!material.id,id=material.id||'new',key=draftKey;return run(async()=>{await api('/conversations/'+props.conversation.id+'/materials'+(editing?'/'+material.id:''),editing?'PATCH':'POST',{user_id:props.settings.userId,...material,due_at:iso(material.due_at)});const d=readFormDraft(key)||{};if(d.materials)delete d.materials[id];delete d.selection;writeFormDraft(key,d)},'材料清单已保存；收到和核验分别记录')}
function pickFile(event){file.value=event.target.files?.[0]||null;event.target.value='';fileReminder.value=file.value?{name:file.value.name,size:file.value.size,lastModified:file.value.lastModified}:null}
async function upload(){if(!file.value||!uploadMaterial.value||!sourceNote.value.trim())return;const identity=[file.value.name,file.value.lastModified,uploadMaterial.value,sourceNote.value.trim()].join(':');if(uploadKey.value?.identity!==identity)uploadKey.value={identity,id:crypto.randomUUID()};const key=draftKey;await run(async()=>{await uploadCaseEvidence(props.settings,props.conversation.id,file.value,{material_id:uploadMaterial.value,source_note:sourceNote.value.trim(),request_id:uploadKey.value.id});file.value=null;fileReminder.value=null;uploadKey.value=null;const d=readFormDraft(key)||{};delete d.upload;writeFormDraft(key,d)},'原始凭证已保存，材料改为已收到，仍需人工核验')}
async function viewFile(a){const key=fingerprint();await run(async()=>{const blob=await getCaseEvidence(props.settings,props.conversation.id,a.id);if(key!==fingerprint())return;closePreview();preview.value={...a,url:URL.createObjectURL(blob)}},'已读取授权范围内的原文件',false)}
function archive(a){return run(()=>api('/conversations/'+props.conversation.id+'/attachments/'+a.id+'/archive','POST',{user_id:props.settings.userId,note:archiveNote.value,expected_revision:a.revision}),'凭证已归档，原文件与原因仍保留；相关材料需要重新核验')}
async function openSection(kind,id){if(!data.value)await load();const section=kind==='material'?materialSection.value:resultSection.value;if(!section)return;section.open=true;if(kind==='material'&&id){const m=data.value.materials.find(m=>m.id===id);if(m)chooseMaterial(m)}await nextTick();section.scrollIntoView({block:'start'});section.querySelector('input,textarea,select')?.focus()}
defineExpose({openSection,load})
</script>
<template>
<section :aria-busy="busy||loading" class="case-followup" aria-label="事项结果与材料">
  <h2>结果与材料</h2><p v-if="error" ref="errorBox" role="alert" tabindex="-1" class="form-error">{{error}} <button class="text-button" :disabled="busy" @click="load">重新读取当前记录</button></p><p v-if="notice" role="status" class="source-note">{{notice}}</p>
  <p v-if="!data" class="source-note">正在读取事项补齐记录…</p>
  <template v-else><details v-if="conversation.status==='resolved'"><summary>核对 / 补录结案后的安排</summary><p v-if="data.customer_followup?.source==='closure_review'" role="alert">此历史结案未登记客户结果或后续安排，仍显示在待办中。</p><form @submit.prevent="saveClosurePlan"><ClosurePlanForm :conversation-id="conversation.id" :settings="settings" :members="members" v-model="closurePlan"/><button class="secondary" :disabled="busy||!closurePlan.kind">保存后续安排</button></form><details v-if="data.closure_plan_history?.length"><summary>安排记录</summary><p v-for="(h,i) in data.closure_plan_history" :key="i">{{h.actor}} · {{display(h.at)}} · {{{followup:'仍需跟进',no_followup:'无需回访',confirmed:'客户已确认'}[h.kind]||h.kind}} · {{h.note}} {{h.owner}} {{h.next_action}}</p></details></details><p v-if="draftNotice" class="form-draft-note" role="status">{{draftNotice}}</p><fieldset class="form-fields" :disabled="busy||loading">
  <details ref="resultSection" class="followup-block"><summary>客户结果 · {{data.customer_confirmation_required?'需重新确认':data.customer_result?resultNames[data.customer_result.status]:'尚未登记'}}</summary>
    <p v-if="data.customer_confirmation_required" role="status" class="source-note">事项已重新打开，上一轮客户确认仅保留为历史。当前待确认由系统建立，不代表客户已反馈；请重新核对并登记本轮结果。</p><p class="source-note">客服人工记录反馈，不代表渠道已读或送达；保存不会自动结案或重开。</p>
    <div v-if="resultConflict" class="draft-conflict" role="alert"><strong>当前记录已更新，你的草稿已保留，尚未覆盖新记录。</strong><p>当前已保存说明：{{data.customer_result?.note||'尚未登记'}}</p><button type="button" class="secondary" @click="rebaseResult">已核对当前记录，保留草稿继续编辑</button><button type="button" class="text-button" @click="discardResult">放弃此草稿，使用当前记录</button></div>
    <form @submit.prevent="saveResult"><label>客户结果<select aria-label="客户结果" v-model="result.status"><option v-for="(label,key) in resultNames" :key="key" :value="key">{{label}}</option></select></label><label>反馈发生时间（上海）<input v-model="result.occurred_at" type="datetime-local" required/></label><label>反馈内容 / 更正说明<textarea v-model.trim="result.note" required maxlength="2000" rows="2"/></label>
      <template v-if="result.status!=='confirmed'"><label>客户跟进负责人<select aria-label="客户跟进负责人" v-model="result.owner" required><option v-for="m in members" :key="m.id" :value="m.id">{{m.id}}</option></select></label><label>客户跟进下一步<textarea v-model.trim="result.next_action" required maxlength="1000" rows="2"/></label><label>客户跟进期限（上海）<input v-model="result.due_at" type="datetime-local" required/></label></template>
      <button class="secondary" :disabled="busy||resultConflict">保存客户结果</button><button type="button" class="text-button" @click="discardResult">清除客户结果未提交内容</button></form>
    <details v-if="data.customer_result_history.length"><summary>客户结果历史 · {{data.customer_result_history.length}}</summary><ol><li v-for="(r,i) in [...data.customer_result_history].reverse()" :key="i"><strong>{{resultNames[r.status]}}</strong><p>{{r.note}}</p><small>反馈 {{display(r.occurred_at)}} · {{r.recorded_by}} · {{r.source==='demo_seed'?'演示预置':r.source==='demo_reopen'?'演示流程标记':'人工录入'}}于 {{display(r.recorded_at)}}</small><p v-if="r.next_action">{{r.owner}} · {{r.next_action}} · {{display(r.due_at)}}</p></li></ol></details>
  </details>
  <details ref="materialSection" class="followup-block"><summary>材料追补 · {{data.materials.filter(m=>['missing','received'].includes(m.status)).length}} 项待办</summary>
    <details class="material-suggestions" open><summary>按当前问题选择建议材料</summary><p class="source-note">先核对已有记录，再勾选确实需要的材料；这是建议清单，不代表客户已提供或必须重复提交。</p><label v-for="s in data.material_suggestions||[]" :key="s.key" class="suggestion-choice"><input v-model="suggestionKeys" type="checkbox" :value="s.key" :disabled="!!s.existing_id"/><span>{{s.name}}<small>{{s.reason}}</small><small v-if="s.existing_id">已有材料 · {{materialNames[s.existing_status]}}，请在原项继续核对</small></span></label><form v-if="data.material_suggestions?.some(s=>!s.existing_id)" @submit.prevent="addSuggestions"><label>建议材料负责人<select v-model="suggestionOwner" aria-label="建议材料负责人" required><option v-for="m in members" :key="m.id" :value="m.id">{{m.id}}</option></select></label><label>建议材料追补期限（上海）<input v-model="suggestionDue" type="datetime-local" required/></label><label class="inline-check"><input v-model="suggestionsRequired" type="checkbox"/>将所选材料设为结案前必要材料</label><button type="submit" class="secondary" :disabled="!suggestionKeys.length||!suggestionOwner||!suggestionDue">添加所选建议材料</button></form></details>
    <label class="inline-check"><input v-model="showArchived" type="checkbox"/>显示撤回材料与归档凭证</label>
    <div class="material-list"><button v-for="m in visibleMaterials" :key="m.id" class="material-row" :aria-pressed="material.id===m.id" @click="chooseMaterial(m)"><strong>{{m.name}} <small>{{m.required?'必要':'补充'}}</small></strong><span>{{materialNames[m.status]}}</span><small>{{m.owner}} · {{display(m.due_at)}}</small></button><p v-if="!visibleMaterials.length" class="source-note">尚无材料清单；可按实际问题逐项建立。</p></div>
    <button class="text-button" :disabled="busy" @click="newMaterial">新建材料项</button><div v-if="materialConflict" class="draft-conflict" role="alert"><strong>材料已被更新，旧草稿已保留。请先核对当前记录。</strong><p>当前状态：{{materialNames[data.materials.find(m=>m.id===material.id)?.status]}}</p><button type="button" class="secondary" @click="rebaseMaterial">已核对材料，保留草稿继续编辑</button><button type="button" class="text-button" @click="discardMaterial">放弃此材料草稿</button></div><form @submit.prevent="saveMaterial"><h3>{{material.id?'更新材料项':'建立材料追补项'}}</h3><label>材料名称<input v-model.trim="material.name" required maxlength="200"/></label><label class="inline-check"><input v-model="material.required" type="checkbox"/>必要材料</label><label>材料负责人<select aria-label="材料负责人" v-model="material.owner" required><option v-for="m in members" :key="m.id" :value="m.id">{{m.id}}</option></select></label><label>材料追补期限（上海）<input v-model="material.due_at" type="datetime-local" required/></label><label>材料状态<select aria-label="材料状态" v-model="material.status"><option v-for="(label,key) in materialNames" :key="key" :value="key">{{label}}</option></select></label><label>核验或变更说明<textarea v-model.trim="material.note" :required="!!material.id||['verified','waived','withdrawn'].includes(material.status)" maxlength="2000" rows="2"/></label><button class="secondary" :disabled="busy||materialConflict">保存材料项</button><button type="button" class="text-button" @click="discardMaterial">清除本材料未提交内容</button></form>
    <details v-if="material.id"><summary>当前材料处理历史</summary><ol><li v-for="(h,i) in data.materials.find(m=>m.id===material.id)?.history||[]" :key="i">{{h.actor}} · {{display(h.at)}}<p>{{h.note}} · {{materialNames[h.status]||''}}</p></li></ol></details>
    <form class="evidence-upload" @submit.prevent="upload"><h3>原始凭证</h3><p class="source-note">PNG / JPEG / WebP / PDF，单文件≤5MB，每事项最多20个活动凭证。归档保留原文件与历史；未配置自动清理。</p><label>凭证对应材料<select aria-label="凭证对应材料" v-model="uploadMaterial" required><option value="">请先建立材料项</option><option v-for="m in uploadMaterials" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label>选择凭证<input type="file" accept=".png,.jpg,.jpeg,.webp,.pdf" :disabled="busy" @change="pickFile"/></label><p v-if="file" class="source-note">已选择 {{file.name}}</p><p v-else-if="fileReminder" class="form-draft-note">之前选择了 {{fileReminder.name}}，请重新选择原文件后上传。文件本体未在浏览器中自动保存。</p><label>凭证来源说明<textarea v-model.trim="sourceNote" required maxlength="2000" rows="2" placeholder="例如：客服从客户来信中人工保存"/></label><button class="secondary" :disabled="busy||!file||!uploadMaterial||!sourceNote.trim()">上传原始凭证</button></form>
    <div class="evidence-files"><article v-for="a in attachments" :key="a.id"><strong>{{a.filename}} {{a.archived?'（已归档）':''}}</strong><p>{{a.source_note}}</p><small>{{a.uploaded_by}} · {{display(a.created_at)}} · {{Math.ceil(a.size/1024)}} KB</small><button class="text-button" :disabled="busy" @click="viewFile(a)">查看或下载原文件</button><button v-if="!a.archived" class="text-button" :disabled="busy||!archiveNote.trim()" @click="archive(a)">按下方原因归档凭证</button><details v-if="a.history.length"><summary>凭证归档历史</summary><p v-for="(h,i) in a.history" :key="i">{{h.actor}} · {{display(h.at)}} · {{h.note}}</p></details></article></div><label v-if="attachments.some(a=>!a.archived)">凭证归档原因<textarea v-model.trim="archiveNote" maxlength="2000" rows="2"/></label>
    <div v-if="preview" class="evidence-preview"><strong>{{preview.filename}}</strong><img v-if="preview.mime.startsWith('image/')" :src="preview.url" :alt="preview.filename"/><p v-else class="source-note">PDF可下载后使用本机阅读器核对。</p><a :href="preview.url" :download="preview.filename">下载当前原文件</a><button class="text-button" @click="closePreview">关闭凭证预览</button></div>
  </details>
  <details v-if="data.rechecks.length" class="followup-block"><summary>关联知识回查 · {{data.rechecks.filter(r=>r.status==='pending').length}} 项待处理</summary><p class="source-note">在“知识与缺口”的影响事项清单中记录回查结论；原事项和采用稿保持原记录。</p><p v-for="r in data.rechecks" :key="r.id">{{r.document_title}} · v{{r.document_version}} · {{({pending:'待回查',reviewed:'已回查',not_applicable:'不适用',superseded:'已转新版'})[r.status]}}<small v-if="!r.document_current"> · 依据已变化或失效</small></p></details>
  </fieldset></template>
</section>
</template>
